// ============================================================================
// src/lib/fun/games/five-clues/puzzles.ts
// ----------------------------------------------------------------------------
// FIVE CLUES, the puzzle pool (PRIME 03/11/2026). Each puzzle is a hidden
// category and five of its members, hardest first. English and Brazilian
// Portuguese sit side by side: the category's name, the answers accepted (in
// both languages, since a Brazilian engineer may well answer in English), and
// the clues (a plain string is the same in both languages, which is the case
// for most technical names).
//
// Every clue was checked against the first-party document named in `source`
// (an RFC, an IANA registry, a manual page, a vendor's documentation); the
// check and the quotes are in the hand-over's SOURCES.md. Puzzles marked
// `warmup` never come up as a daily puzzle: they are the practice archive's
// first entries, so practice has something to play before thirty days exist.
//
// Data, not code: one comment per puzzle names what it is about.
// ============================================================================

/** A clue that differs between the two languages. */
export interface Clue {
  /** In English. */
  en: string;
  /** In Brazilian Portuguese. */
  pt: string;
}

/** One puzzle. */
export interface FivePuzzle {
  /** A stable id. */
  id: string;
  /** The category, as revealed at the end. */
  cat: Clue;
  /** Accepted answers in each language (the first is the main answer). */
  answers: { en: string[]; pt: string[] };
  /** Five members of the category, hardest first; a string is the same in both languages. */
  clues: (string | Clue)[];
  /** The first-party document that lists the members. */
  source: { label: string; url: string };
  /** Practice only, never a daily puzzle. */
  warmup?: true;
}

